import Foundation

private func lateTrainingCard(_ day: Int, _ title: String, _ standard: String, _ minimum: String, _ regression: String, _ stop: String, _ prompts: [String], _ minutes: Int) -> TrainingCard {
    TrainingCard(dayIndex: day, title: title, standardVersion: standard, minimumVersion: minimum, regression: regression, stopConditions: stop, followAlongInstruction: "优先选择 B 站零基础无器械跟练；跟不上时只完成最低版，不追视频节奏。", cameraPrompts: prompts, maxMinutes: minutes)
}

